export const grantOverride = createServerFn({ method: "POST" })
.middleware([requireSupabaseAuth])
.inputValidator((d: { accountId: string; capabilityId: string; reason: string }) => d)
.handler(async ({ data, context }) => {
await requirePlatformAdmin(context.userId);
const { accountId, capabilityId, reason } = data;

const { error } = await serviceSupabase.from("account_entitlement_overrides").upsert(
{ account_id: accountId, capability_id: capabilityId, granted: true, reason },
{ onConflict: "account_id,capability_id" }
);
if (error) throw new Error(`OVERRIDE_GRANT_FAILURE: ${error.message}`);

await logEntitlementChange({
accountId, changedBy: context.userId, changeType: "grant_override",
entityType: "account_entitlement_override", entityId: capabilityId,
newValue: { granted: true, reason },
});
return { success: true };
});

