export const grantOverride = createServerFn({ method: "POST" })
.middleware([requireSupabaseAuth])
.inputValidator((d: { accountId: string; capabilityId: string; reason: string }) => d)
.handler(async ({ data, context }) => {
await requirePlatformAdmin(context.userId);
const { accountId, capabilityId, reason } = data;
// Atomic RPC: override + audit in single transaction
const { error } = await serviceSupabase.rpc("upsert_entitlement_override_with_audit", {
p_account_id: accountId,
p_capability_id: capabilityId,
p_granted: true,
p_reason: reason,
p_changed_by: context.userId,
});
if (error) throw new Error(`ATOMIC_OVERRIDE_GRANT_FAILURE: ${error.message}`);
return { success: true };
});

